/** Generates docs/CALCULATORS.md from the calculator catalogue (ids, rules, limitations, examples). */
import { writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { calculators } from '../src/calculators.js';
import { runCalculator } from '../src/core/calculator.js';
import { defaultRegistry } from '../src/params.js';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const lines: string[] = [
  '# Calculator catalogue (generated — do not edit)',
  '',
  'Generated by `npm run docs` from `src/calculators.ts`. Each calculator is available in the web UI and at `POST /api/v1/calculate/<id>`.',
  'Status of the shipped example against the current parameter release is shown so readers can see what is blocked.',
  '',
  '| Calculator | Domain | Example status |',
  '|---|---|---|',
];
const details: string[] = [];
for (const c of calculators) {
  const res = runCalculator(c, c.example, defaultRegistry());
  lines.push(`| [\`${c.id}\`](#${c.id.replace(/\./g, '')}) — ${c.title} | ${c.domain} | ${res.status}${res.status === 'blocked' ? ` (${res.blocked?.map((b) => b.code).join(', ')})` : ''} |`);
  details.push(
    `## ${c.id}`,
    '',
    `**${c.title}** — ${c.summary}`,
    '',
    '**Rules:**',
    ...c.rules.map((r) => `- \`${r.id}\` v${r.version} — ${r.legalReference}`),
    '',
    '**Limitations:**',
    ...c.limitations.map((l) => `- ${l}`),
    '',
    '**Example request:**',
    '',
    '```json',
    JSON.stringify(c.example, null, 2),
    '```',
    '',
  );
}
writeFileSync(join(root, 'docs', 'CALCULATORS.md'), [...lines, '', ...details].join('\n'));
console.log(`docs/CALCULATORS.md written (${calculators.length} calculators)`);
